void input(int a[],int size){
  int i=0;
   while(i<size)
     {scanf("%d",&a[i]);
      i++;
     } 
}
int check(int a[],int b[],int s1,int s2){
   int i,j=0,flag=-1;
    for(i=0;i<s1;i++)
     { if(a[i]==b[j])
        { flag=1;
          i++;j++;
          while(i<s1&&j<s2)
           { if(a[i]!=b[j])
              {flag=-1;
                i--;j=0;
                break;
              }
              i++;j++;

           }
        }     
     }
    return flag;
}    
