int check_arrays(int B1[],int B2[],int c1,int c2)
{
    int i,c=0;
    for(i=0;i<c1-c2;i++)
    {
        if(B2[0]==B1[i])
        {
         c=1;
         break;
        }
    }
    if(c==0)
    return 0;
    int j=0;
    while(j<c2)
    {
        j++;
        i++;
        if((B2[j])!=B1[i])
        return 0;
    }
    return 1;
}

